#!/bin/bash\n\n# DevCare Stretch n8n 설정 및 실행 스크립트\n\nset -e\n\necho \"🚀 DevCare Stretch n8n 설정을 시작합니다...\"\n\n# 색상 정의\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# 함수 정의\nprint_status() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Docker 설치 확인\ncheck_docker() {\n    print_status \"Docker 설치 상태를 확인합니다...\"\n    if ! command -v docker &> /dev/null; then\n        print_error \"Docker가 설치되어 있지 않습니다.\"\n        echo \"Docker 설치 가이드: https://docs.docker.com/get-docker/\"\n        exit 1\n    fi\n    \n    if ! command -v docker-compose &> /dev/null; then\n        print_error \"Docker Compose가 설치되어 있지 않습니다.\"\n        echo \"Docker Compose 설치 가이드: https://docs.docker.com/compose/install/\"\n        exit 1\n    fi\n    \n    print_success \"Docker 및 Docker Compose가 설치되어 있습니다.\"\n}\n\n# 환경 변수 파일 설정\nsetup_env() {\n    print_status \"환경 변수 파일을 설정합니다...\"\n    \n    if [ ! -f \".env\" ]; then\n        print_status \"n8n.env.example을 .env로 복사합니다...\"\n        cp n8n.env.example .env\n        print_warning \"⚠️  .env 파일을 편집하여 실제 API 키들을 입력해주세요!\"\n        echo \"   편집할 파일: $(pwd)/.env\"\n        echo\n        echo \"   필요한 API 키들:\"\n        echo \"   - YOUTUBE_API_KEY (Google Cloud Console)\"\n        echo \"   - OPENAI_API_KEY (OpenAI Platform)\"\n        echo \"   - GEMINI_API_KEY (Google AI Studio)\"\n        echo \"   - SLACK_BOT_TOKEN (Slack App)\"\n        echo \"   - SLACK_SIGNING_SECRET (Slack App)\"\n        echo \"   - SUPABASE_URL (Supabase Dashboard)\"\n        echo \"   - SUPABASE_SERVICE_KEY (Supabase Dashboard)\"\n        echo\n        read -p \"API 키 설정을 완료했습니까? (y/N): \" -n 1 -r\n        echo\n        if [[ ! $REPLY =~ ^[Yy]$ ]]; then\n            print_warning \"API 키 설정을 완료한 후 다시 실행해주세요.\"\n            exit 1\n        fi\n    else\n        print_success \".env 파일이 이미 존재합니다.\"\n    fi\n}\n\n# n8n 컨테이너 시작\nstart_n8n() {\n    print_status \"n8n 컨테이너를 시작합니다...\"\n    \n    # 기존 컨테이너 정리\n    docker-compose -f docker-compose.n8n.yml down 2>/dev/null || true\n    \n    # 새 컨테이너 시작\n    docker-compose -f docker-compose.n8n.yml up -d\n    \n    print_status \"n8n이 시작되기를 기다립니다...\"\n    sleep 10\n    \n    # 컨테이너 상태 확인\n    if docker-compose -f docker-compose.n8n.yml ps | grep -q \"Up\"; then\n        print_success \"n8n이 성공적으로 시작되었습니다!\"\n        echo\n        echo \"🌐 n8n 웹 인터페이스: http://localhost:5678\"\n        echo \"👤 사용자명: admin\"\n        echo \"🔐 비밀번호: devcare2024!\"\n        echo\n    else\n        print_error \"n8n 시작에 실패했습니다.\"\n        echo \"로그를 확인해보세요:\"\n        echo \"docker-compose -f docker-compose.n8n.yml logs\"\n        exit 1\n    fi\n}\n\n# 워크플로우 가이드 출력\nprint_workflow_guide() {\n    echo \"📋 다음 단계: 워크플로우 Import\"\n    echo \"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\"\n    echo \"1. 브라우저에서 http://localhost:5678 접속\"\n    echo \"2. admin / devcare2024! 로 로그인\"\n    echo \"3. 좌측 메뉴에서 'Workflows' 클릭\"\n    echo \"4. 'Import from file' 버튼 클릭\"\n    echo \"5. 다음 파일들을 순서대로 import:\"\n    echo \"   📁 n8n-workflows/youtube-data-ingestion.json\"\n    echo \"   📁 n8n-workflows/slack-notifications.json\"\n    echo \"6. 각 워크플로우를 열어서 'Active' 토글 켜기\"\n    echo \"7. 'Save' 버튼 클릭\"\n    echo\n    echo \"📖 상세한 설정 가이드: docs/n8n-setup-guide.md\"\n    echo\n}\n\n# 메인 실행 함수\nmain() {\n    echo \"═══════════════════════════════════════════════════════════════\"\n    echo \"🚀 DevCare Stretch - n8n 자동화 플랫폼 설정\"\n    echo \"═══════════════════════════════════════════════════════════════\"\n    echo\n    \n    check_docker\n    setup_env\n    start_n8n\n    print_workflow_guide\n    \n    print_success \"n8n 설정이 완료되었습니다! 🎉\"\n}\n\n# 스크립트 실행\nmain \"$@\""